  \proofstepwidestarbreakkeep[1]{\MonoidAlg{G}{\star}{e}}{\FormulaRefAuto{GroupBaseMonoidAxiom}[ax]{1}}
  \proofstepwidestarbreakkeep[1,2]{\begin{aligned}[t]
    &\MonoidUnit{\PowNE G,\star_{\mathcal P},\{e\}}{X}\\[-2pt]
    &\quad\leftrightarrow\exists g\in G\,(X=\{g\}\land\MonoidUnit{G,\star,e}{g})
  \end{aligned}}{\FormulaRefAuto{PowerMonoidUnitCharacterization}[thm]{3,2}}
  \proofstepwidestarbreakkeep[5]{%
    \exists g\in G\,(X=\{g\}\land\MonoidUnit{G,\star,e}{g})}{\rA}
  \proofstepwidestarbreakkeep[6]{%
    g\in G\land(X=\{g\}\land\MonoidUnit{G,\star,e}{g})}{\rA}
