    \rEI{\rAI{7,8}}}
  \proofstepwidestarbreakkeep[5]{\exists g\in G\,(X=\{g\})}{\rEE{5,6,9}}
  \proofstepwidestarbreakkeep[]{\begin{aligned}[t]
    &\exists g\in G\,(X=\{g\}\land\MonoidUnit{G,\star,e}{g})\\[-2pt]
    &\quad\rightarrow\exists g\in G\,(X=\{g\})
