  \proofstepwidestarbreakkeep[12]{\exists g\in G\,(X=\{g\})}{\rA}
  \proofstepwidestarbreakkeep[13]{g\in G\land X=\{g\}}{\rA}
  \proofstepwidestarbreakkeep[13]{g\in G}{\rAEa{13}}
