    \exists g\in G\,(X=\{g\}\land\MonoidUnit{G,\star,e}{g})}{%
    \rEI{\rAI{14,\rAI{15,16}}}}
  \proofstepwidestarbreakkeep[1,12]{%
    \exists g\in G\,(X=\{g\}\land\MonoidUnit{G,\star,e}{g})}{%
    \rEE{12,13,17}}
  \proofstepwidestarbreakkeep[1]{\begin{aligned}[t]
    &\exists g\in G\,(X=\{g\})\\[-2pt]
    &\quad\rightarrow\exists g\in G\,(X=\{g\}\land\MonoidUnit{G,\star,e}{g})
  \end{aligned}}{\rRI{12,18}}
  \proofstepwidestarbreakkeep[1]{\begin{aligned}[t]
    &\exists g\in G\,(X=\{g\}\land\MonoidUnit{G,\star,e}{g})\\[-2pt]
    &\quad\leftrightarrow\exists g\in G\,(X=\{g\})
  \end{aligned}}{\rLRI{11,19}}
  \proofstepwidestar[1]{\SemigroupAlg{G}{\star}}{%
